CREATE TABLE IF NOT EXISTS ward_evidence_artifacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_key text NOT NULL, artifact_name text NOT NULL, resource_type text NOT NULL, source_reference text NOT NULL, version_label text, content_hash text NOT NULL, provenance_status text NOT NULL DEFAULT 'UNVERIFIED', verification_status text NOT NULL DEFAULT 'PENDING', received_at timestamptz NOT NULL DEFAULT now(), notes text);